  "„Alle erinnern“ in den Beiträgen wartet so viele Tage nach der Fälligkeit und kann einen Zusatztext anhängen.": "„Przypomnij wszystkim“ w składkach czeka tyle dni po terminie płatności i może dołączyć dodatkowy tekst.",
  "„Anlage & Material“ ist im Verein nicht aktiviert.": "„Obiekty i sprzęt“ nie są włączone w klubie.",
  "„Automatisch zugesagt“ ist empfohlen; bei aktiver Antwort gilt jede Person als offen, bis sie antwortet. Änderungen gelten für neue Termine.": "Zalecane jest „Automatycznie potwierdzone”; przy aktywnej odpowiedzi każdy jest otwarty, dopóki nie odpowie. Zmiany dotyczą nowych wydarzeń.",
  "„Fällige Beiträge anlegen“ erzeugt für alle zugeordneten Mitglieder die Forderungen, die bis heute fällig sind – nie doppelt.": "„Utwórz wymagalne składki“ tworzy dla wszystkich przypisanych członków należności wymagalne do dziś – nigdy podwójnie.",
  "„Ich → Einstellungen → Einladen“ oder im Team „Person zur Mannschaft einladen“: persönlich per E-Mail oder als Mannschafts-Link bzw. QR-Code zum Selbstregistrieren. Bei Links gibst du neue Anfragen frei, bevor jemand die App nutzen kann.": "„Ja → Ustawienia → Zaproś“ lub w zespole „Zaproś osobę do drużyny“: osobiście e-mailem albo jako link drużyny lub kod QR do samodzielnej rejestracji. W przypadku linków zatwierdzasz nowe prośby, zanim ktoś będzie mógł korzystać z aplikacji.",
  "„Mannschaft bearbeiten → Spielplan importieren“: CSV-Datei aus dem DFBnet wählen, Vorschau prüfen (neu, geändert, unverändert, übersprungen) und übernehmen. Die Mannschaft bekommt eine Sammelmeldung. Ein erneuter Import aktualisiert Verlegungen, statt Spiele doppelt anzulegen. Innerhalb von 24 Stunden kannst du den Import rückgängig machen.": "„Edytuj drużynę → Importuj terminarz“: wybierz plik CSV z DFBnet, sprawdź podgląd (nowe, zmienione, bez zmian, pominięte) i zatwierdź. Drużyna dostaje zbiorcze powiadomienie. Ponowny import aktualizuje przesunięcia zamiast tworzyć mecze podwójnie. W ciągu 24 godzin możesz cofnąć import.",
  "„Team → Kader → Mannschaft bearbeiten“: Spieler aus der Vereinsliste hinzufügen oder aus dem Kader nehmen, Funktion (Spieler, Co-Trainer, Betreuer) und Rückennummer ändern, den Kassenwart bestimmen. Unten stellst du ein, wie viele Minuten vor Spielen und Trainings ihr euch trefft, den Standard-Treffpunkt und die Schreibweisen eurer Mannschaft im DFBnet. Co-Trainer haben dieselben Rechte wie der Trainer.": "„Zespół → Kadra → Edytuj drużynę“: dodawaj zawodników z listy klubu lub usuwaj ich z kadry, zmieniaj funkcję (zawodnik, asystent trenera, opiekun) i numer na koszulce, wyznacz skarbnika. Na dole ustawiasz, ile minut przed meczami i treningami się spotykacie, domyślne miejsce zbiórki i pisownię nazwy waszej drużyny w DFBnet. Asystenci trenera mają takie same uprawnienia jak trener.",
  "„Team → Kasse → Kassenverwaltung“. Dort liegen als Kacheln: Einnahme/Ausgabe, Einzahlungen, Strafe vergeben, Getränke-Strichliste, Umlage, Beiträge, Buchungen & Storno, Kassenwart, Bezahlinfos und Kassenprüfung.": "„Zespół → Kasa → Zarządzanie kasą“. Tam znajdziesz kafelki: przychód/wydatek, wpłaty, nałożenie kary, lista napojów, składka zrzutowa, składki, księgowania i storno, skarbnik, informacje o płatnościach i kontrola kasy.",
  "„Team → Termin anlegen“: Training, Spiel oder Mannschaftstermin. Spiele bekommen die Art Liga, Pokal oder Testspiel. Zum Wiederholen wählst du „Wöchentlich bis …“ und das Enddatum (bis zu etwa einem Jahr). Die Treffzeit berechnet die App aus den Regeln deiner Mannschaft; im einzelnen Termin kannst du sie überschreiben. Im Termin änderst du mit „Termin bearbeiten“ einzelne Termine oder „diesen und folgende“. Mit „Termin absagen“ wird die Mannschaft sofort benachrichtigt.": "„Zespół → Utwórz termin“: trening, mecz lub termin drużyny. Mecze dostają rodzaj: liga, puchar lub sparing. Aby powtarzać, wybierasz „Co tydzień do …“ i datę końcową (do około roku). Godzinę zbiórki aplikacja wylicza z zasad twojej drużyny; w pojedynczym terminie możesz ją nadpisać. W terminie przez „Edytuj termin“ zmieniasz pojedyncze terminy lub „ten i kolejne“. Przez „Odwołaj termin“ drużyna jest natychmiast powiadamiana.",
  "„Unsicher“ als Antwort erlauben": "Zezwól na odpowiedź „Niepewne“",
