  "Auch Mitspieler sehen den Grund einer Absage oder Abwesenheit (z. B. verletzt, krank).": "Współgracze także widzą powód odwołania lub nieobecności (np. kontuzja, choroba).",
  "Auch ohne Werbung bleibt der Sponsor in der Übersicht sichtbar.": "Także bez reklamy sponsor pozostaje widoczny w przeglądzie.",
  "Audit-Log einsehen": "Podgląd dziennika audytu",
  "Auf der letzten Seite findest du die passenden Schaltflächen.": "Na ostatniej stronie znajdziesz odpowiednie przyciski.",
  "Auf der Startseite und unter „Verein → News“. Dringende Meldungen stehen oben und erreichen dich auch per Push. Mit „Gefällt mir“ und Kommentaren kannst du reagieren.": "Na stronie głównej i w „Klub → Aktualności“. Pilne komunikaty są na górze i docierają do ciebie także przez push. Możesz reagować przez „Lubię to“ i komentarze.",
  "Auf die Forderung wurde schon gezahlt. Storniere zuerst die Buchung im Kassenbuch.": "Na tę należność wpłynęła już płatność. Najpierw anuluj księgowanie w księdze kasowej.",
  "Auf jeder Unterseite siehst du oben deinen Weg, zum Beispiel „Team › Kasse › Strafenkatalog“. Tippe auf eine frühere Stufe, um dorthin zurückzugehen, oder auf den runden Pfeil für einen Schritt zurück. Bei langen Wegen steht „…“ für die ausgelassenen Stufen; ein Tipp zeigt sie als Liste. Die untere Leiste bleibt sichtbar, der aktuelle Bereich ist markiert.": "Na każdej podstronie widzisz u góry swoją ścieżkę, na przykład „Zespół › Kasa › Taryfikator kar“. Dotknij wcześniejszego poziomu, aby tam wrócić, lub okrągłej strzałki, aby cofnąć się o krok. Przy długich ścieżkach „…“ oznacza pominięte poziomy; dotknięcie pokazuje je jako listę. Dolny pasek pozostaje widoczny, bieżący obszar jest zaznaczony.",
