  "Aus diesen Regeln berechnet die App bei jedem neuen Spiel und Training die Treffzeit. Beim einzelnen Termin kannst du sie jederzeit überschreiben. Leer lassen = kein automatisches Treffen.": "Z tych zasad aplikacja wylicza godzinę zbiórki przy każdym nowym meczu i treningu. W pojedynczym terminie możesz ją w każdej chwili nadpisać. Puste = brak automatycznej zbiórki.",
