  "Beginnt am {0}. Kader planst du unter Verwaltung → Mitglieder: Mannschaften der neuen Saison sind dort mit „(Saison {1})“ gekennzeichnet.": "Zaczyna się {0}. Kadry planujesz w Administracja → Członkowie: drużyny nowego sezonu są tam oznaczone „(sezon {1})“.",
  "Begründung": "Uzasadnienie",
  "Begründung (bei Ablehnung)": "Uzasadnienie (przy odrzuceniu)",
  "Begründung für das Storno": "Uzasadnienie storna",
  "Begünstigter Zweck": "Cel uprzywilejowany",
  "Bei „Nur der Kassenwart“ dürfen Trainer ohne Kassenwart-Aufgabe nichts mehr buchen und keine Strafen vergeben; sie sehen die Kasse weiterhin.": "Przy „Tylko skarbnik” trenerzy bez zadania skarbnika nie mogą już księgować ani nakładać kar; nadal widzą kasę.",
  "Bei Auswärtsspielen und Turnieren gibt es im Termin den Bereich „Fahrgemeinschaften“. Tippe auf „Ich fahre“ und gib die freien Plätze an, oder wähle bei einem Auto „Mitfahren“. Wer keine Mitfahrt hat, tippt auf „Mitfahrt suchen“. Eltern buchen für ihre Kinder.": "Przy meczach wyjazdowych i turniejach w terminie jest sekcja „Wspólne dojazdy“. Dotknij „Jadę“ i podaj wolne miejsca albo przy aucie wybierz „Jadę z kimś“. Kto nie ma podwózki, dotyka „Szukam podwózki“. Rodzice rezerwują dla swoich dzieci.",
  "Bei der Anmeldung schicken wir dir einen 6-stelligen Code per E-Mail (10 Minuten gültig, nur einmal nutzbar). Sicherer ist eine Authenticator-App – der E-Mail-Code ist die einfachere Alternative.": "Przy logowaniu wyślemy ci 6-cyfrowy kod e-mailem (ważny 10 minut, jednorazowy). Bezpieczniejsza jest aplikacja uwierzytelniająca – kod e-mail to prostsza alternatywa.",
  "Bei dir": "U ciebie",
  "Bei Dubletten": "Przy duplikatach",
  "Bei einer Absage ist ein Grund Pflicht": "Przy odwołaniu powód jest obowiązkowy",
  "Bei Spielen fehlt der Gegner.": "W meczach brakuje przeciwnika.",
  "bei Spielen Pflicht": "obowiązkowe przy meczach",
  "Bei Terminen fehlt der Titel.": "W terminach brakuje tytułu.",
  "bei Terminen Pflicht, sonst automatisch": "obowiązkowe przy terminach, w innym razie automatycznie",
  "Bei Terminen siehst du die Antwort für jede Person. Zu- und Absagen gelten je Kind.": "W terminach widzisz odpowiedź każdej osoby. Potwierdzenia i odwołania dotyczą każdego dziecka osobno.",
  "Bei Vereinsveranstaltungen (z. B. Jahreshauptversammlung, Turnier) kannst du Zusagen, Absagen oder „Unsicher“ wählen – ohne Begründung. Zusätzlich gibt es oft „Helfer gesucht“: Trage dich in eine Schicht ein.": "Przy wydarzeniach klubowych (np. walne zebranie, turniej) możesz wybrać potwierdzenie, odwołanie lub „Niepewne“ – bez uzasadnienia. Często jest też „Szukamy pomocników“: zapisz się na zmianę.",
  "beidfüßig": "obunożny",
  "Beidfüßig": "Obunożny",
  "Beim Austritt werden alle Mannschaftszuordnungen beendet, Rollen entzogen und der App-Zugang gesperrt. Die Daten bleiben für die Vereinsunterlagen erhalten.": "Przy wystąpieniu wszystkie przypisania do drużyn są kończone, role odbierane, a dostęp do aplikacji blokowany. Dane pozostają w dokumentacji klubu.",
  "Beim Buchen einer Einnahme wählst du den Sponsor aus (Verein → Sponsoren).": "Przy księgowaniu przychodu wybierasz sponsora (Klub → Sponsorzy).",
  "Beim Eigentor des Gegners gibt es keinen Torschützen.": "Przy samobóju przeciwnika nie ma strzelca bramki.",
  "Beim Kassenwart oder Trainerteam": "U skarbnika lub w sztabie szkoleniowym",
  "Beim Löschen werden die automatischen Absagen zurückgenommen. Bei Mannschaften mit aktiver Zu-/Absage ist die Rückmeldung danach wieder offen.": "Przy usunięciu automatyczne odwołania są cofane. W drużynach z aktywnym potwierdzaniem/odwoływaniem odpowiedź jest potem znów otwarta.",
  "Beim Planen einer Veranstaltung wählst du oben die Gruppe („Ganzer Verein“, eine Abteilung …). Mit „Mannschaften oder Personen auswählen“ lädst du gezielt ein: Setze im Fenster Häkchen bei Mannschaften oder suche Personen. Die Auswahl erscheint als Chips; mit „×“ nimmst du jemanden wieder heraus. Nur die Eingeladenen werden benachrichtigt. Einzelne Personen darfst du nur mit dem Recht für die Mitgliederliste einladen.": "Przy planowaniu wydarzenia wybierasz u góry grupę („Cały klub“, sekcja …). Przez „Wybierz drużyny lub osoby“ zapraszasz celowo: w oknie zaznacz drużyny lub wyszukaj osoby. Wybór pojawia się jako chipy; przez „×“ ponownie kogoś usuwasz. Powiadomieni zostaną tylko zaproszeni. Pojedyncze osoby możesz zapraszać tylko z uprawnieniem do listy członków.",
  "Beim Start und nach einer Minute im Hintergrund fragt die App nach Face ID, Fingerabdruck oder dem Gerätecode. Die Einstellung gilt nur auf diesem Gerät.": "Przy uruchomieniu i po minucie w tle aplikacja prosi o Face ID, odcisk palca lub kod urządzenia. Ustawienie dotyczy tylko tego urządzenia.",
  "Beispiel": "Przykład",
