  "Beispieltext: Die Haftung richtet sich nach den gesetzlichen Vorschriften. Details folgen in der endgültigen Fassung.": "Tekst przykładowy: odpowiedzialność wynika z przepisów prawa. Szczegóły w wersji ostatecznej.",
