  "Bereite die nächste Saison vor: Alle Mannschaften werden mit Modulen, Fristen, Trainerteams und Zusatzaufgaben (z. B. Kassenwart) übernommen. Die laufende Saison bleibt unverändert, bis du die neue startest.": "Przygotuj następny sezon: wszystkie drużyny zostaną przejęte z modułami, terminami, sztabami szkoleniowymi i dodatkowymi zadaniami (np. skarbnik). Bieżący sezon pozostaje bez zmian, dopóki nie rozpoczniesz nowego.",
