  "Buchen, Strafen vergeben, Einzahlungen erfassen und den Strafenkatalog pflegen – gemeinsam mit dem Kassenwart. Alles Weitere steht im Abschnitt „Kassenverwaltung“.": "Księgowanie, nakładanie kar, rejestrowanie wpłat i prowadzenie taryfikatora kar – razem ze skarbnikiem. Wszystko inne znajdziesz w sekcji „Zarządzanie kasą“.",
