  "Buchungen werden nie gelöscht, sondern storniert: „Buchungen & Storno“, Buchung antippen, optional Grund eintragen. Die Buchung bleibt durchgestrichen sichtbar und steht im Änderungsprotokoll. Zum Korrigieren neu buchen.": "Księgowania nigdy nie są usuwane, tylko anulowane: „Księgowania i storno“, dotknij księgowania, opcjonalnie wpisz powód. Księgowanie pozostaje widoczne jako przekreślone i trafia do dziennika zmian. Aby skorygować, zaksięguj na nowo.",
  "Buchungen, Strafen und Getränke erfassen": "Rejestrowanie księgowań, kar i napojów",
  "Buchungen, Strafen und Getränke erfassen. Lesen darf die Mannschaft ohnehin nach den Einstellungen unter „Was darf die Mannschaft sehen?“.": "Wprowadzanie księgowań, kar i napojów. Odczyt drużyna ma i tak według ustawień w „Co może widzieć drużyna?”.",
