  "Das Haushaltsjahr lässt sich nicht mehr ändern, weil schon ein Jahr abgeschlossen wurde.": "Roku budżetowego nie można już zmienić, ponieważ jeden rok został już zamknięty.",
  "Das Haushaltsjahr lässt sich nur ändern, solange noch kein Jahr abgeschlossen ist.": "Rok budżetowy można zmienić tylko dopóki żaden rok nie został zamknięty.",
