  "Das ist der Standard für neu angelegte Personen; jede Person ändert ihn für sich im Profil.": "To ustawienie domyślne dla nowo utworzonych osób; każda osoba zmienia je dla siebie w profilu.",
  "Das ist für Gemeinnützigkeit und Kassenprüfung wichtig. Die Einbindung in die Vereinskasse ist ein eigener Schritt für später.": "To ważne dla statusu pożytku publicznego i kontroli kasy. Powiązanie z kasą klubu to osobny krok na później.",
  "Das ist kein gültiger Einladungscode. Prüfe den Code oder den Link und versuche es erneut.": "To nie jest prawidłowy kod zaproszenia. Sprawdź kod lub link i spróbuj ponownie.",
