  "Das Jahr {0} ist abgeschlossen. Buchungen sind dort gesperrt; nur die Administration kann es wieder öffnen.": "Rok {0} jest zamknięty. Księgowania są w nim zablokowane; ponownie otworzyć go może tylko administracja.",
