  "Das Jahr ist ungültig.": "Rok jest nieprawidłowy.",
  "Das Kind zu „Elternteil von“ wurde nicht gefunden: {0}. Bitte Namen oder Mitgliedsnummer prüfen.": "Nie znaleziono dziecka dla „Rodzic dziecka“: {0}. Sprawdź imię i nazwisko lub numer członkowski.",
  "Das Konto": "Konto",
  "Das Konto ist archiviert.": "Konto jest zarchiwizowane.",
  "Das Kürzel „{0}“ ist in dieser Saison vergeben.": "Skrót „{0}“ jest w tym sezonie zajęty.",
  "Das Kürzel (2 bis 4 Zeichen, z. B. „SGW“) steht groß im Plakat der Startseite und ersetzt das Wappen, solange kein Logo hochgeladen ist. Die Vereinsadministration ändert es unter „Verwaltung → Verein & Design“, mit Vorschau. Die Vibration bei Auswahl und Bestätigung schaltest du auf dem Handy unter „Ich → Konto & Einstellungen → Vibration“ aus; bei eingestellter „Bewegung reduzieren“ des Geräts bleiben auch die Animationen aus.": "Skrót (2 do 4 znaków, np. „SGW“) jest wyświetlany dużą czcionką na plakacie strony głównej i zastępuje herb, dopóki nie wgrano logo. Administracja klubu zmienia go w „Administracja → Klub i wygląd“, z podglądem. Wibracje przy wyborze i potwierdzeniu wyłączasz w telefonie w „Ja → Konto i ustawienia → Wibracje“; przy ustawionym w urządzeniu „Ogranicz ruch“ animacje również są wyłączone.",
  "Das Kürzel besteht aus 2 bis 4 Buchstaben oder Ziffern.": "Skrót składa się z 2 do 4 liter lub cyfr.",
  "Das Kürzel steht groß im Plakat auf der Startseite und ersetzt das Wappen, solange kein Logo hochgeladen ist.": "Skrót jest wyświetlany dużą czcionką na plakacie na stronie głównej i zastępuje herb, dopóki nie wgrano logo.",
  "Das laufende Jahr kann erst nach seinem Ende abgeschlossen werden.": "Bieżący rok można zamknąć dopiero po jego zakończeniu.",
  "Das Logo erscheint oben in der App bei allen Mitgliedern.": "Logo pojawia się u góry aplikacji u wszystkich członków.",
  "Das Logo konnte nicht gelesen werden.": "Nie udało się odczytać logo.",
  "Das Logo konnte nicht gespeichert werden.": "Nie udało się zapisać logo.",
  "Das Mannschaftsprofil bearbeitet nur das Trainerteam.": "Profil drużyny edytuje tylko sztab szkoleniowy.",
