  "Das Scannen eines QR-Codes ist in der App auf dem Handy möglich.": "Skanowanie kodu QR jest możliwe w aplikacji na telefonie.",
  "Das sieht nur die Kassenführung des ganzen Vereins.": "Widzi to tylko zarząd kasy całego klubu.",
  "Das sind alle Termine.": "To wszystkie terminy.",
  "Das sind optionale Funktionen, die dein Verein einschalten kann: Fundbüro & Marktplatz für Gesuchtes und Gefundenes, ein kleines Forum für wenige Themen und Vereinswissen mit Artikeln wie „Wo gibt es den Schlüssel?“. Sie erscheinen nur, wenn sie aktiv sind.": "To opcjonalne funkcje, które twój klub może włączyć: biuro rzeczy znalezionych i giełda dla rzeczy poszukiwanych i znalezionych, małe forum na kilka tematów oraz wiedza klubowa z artykułami typu „Gdzie jest klucz?“. Pojawiają się tylko, gdy są aktywne.",
  "Das Soll pflegen Administration und Verantwortliche.": "Plan docelowy prowadzą administracja i osoby odpowiedzialne.",
