  "Das Sponsoren-Modul ist nicht aktiviert.": "Moduł sponsorów nie jest włączony.",
  "Das Thema": "Temat",
  "Das Thema ist geschlossen – Antworten sind nicht mehr möglich.": "Temat jest zamknięty – odpowiedzi nie są już możliwe.",
  "Das Thema ist geschlossen.": "Temat jest zamknięty.",
  "Das Trainerteam kann die Spielform bei jeder Aufstellung wechseln.": "Sztab szkoleniowy może zmienić rodzaj gry przy każdym składzie.",
  "Das Trainerteam kann mitbuchen – wenig Aufwand, die Kasse hängt nicht an einer Person": "Sztab trenerski też może księgować – mało wysiłku, kasa nie zależy od jednej osoby",
  "Das Trainerteam sieht Grund und Freitext immer, Eltern die Gründe ihres Kindes. Ob auch die Mitspieler die Gründe sehen, stellt das Trainerteam in „Mannschaft bearbeiten“ ein („Abwesenheitsgründe für die Mannschaft sichtbar“, Standard aus).": "Sztab szkoleniowy zawsze widzi powód i tekst dowolny, rodzice powody swojego dziecka. Czy współgracze też widzą powody, ustawia sztab szkoleniowy w „Edytuj drużynę“ („Powody nieobecności widoczne dla drużyny“, domyślnie wyłączone).",
  "Das Trainerteam von {0} prüft deine Anfrage. Sobald sie freigegeben ist, bekommst du eine E-Mail und kannst dich anmelden.": "Sztab szkoleniowy drużyny {0} sprawdza twoją prośbę. Gdy zostanie zatwierdzona, dostaniesz e-mail i będziesz mógł(-ła) się zalogować.",
  "Das Training": "Trening",
