  "Das Vereinswissen ist nicht aktiviert.": "Wiedza klubowa nie jest włączona.",
  "Das Wichtigste steht, {0} Einladungen sind unterwegs. Hier sind sinnvolle nächste Schritte – alles lässt sich später in der Verwaltung ändern.": "Najważniejsze gotowe, zaproszeń w drodze: {0}. Oto sensowne kolejne kroki – wszystko można później zmienić w administracji.",
  "Das Wichtigste steht, dazu {0} Trainingstermine.": "Najważniejsze gotowe, do tego terminów treningów: {0}.",
  "Das Wichtigste steht. Alles lässt sich in der Kasse der Mannschaft ändern.": "Najważniejsze gotowe. Wszystko można zmienić w kasie drużyny.",
  "Das Wichtigste steht. Hier sind sinnvolle nächste Schritte – alles lässt sich später in der Verwaltung ändern.": "Najważniejsze gotowe. Oto sensowne kolejne kroki – wszystko można później zmienić w administracji.",
  "Das Wichtigste steht. Sinnvolle nächste Schritte – alles lässt sich später ändern.": "Najważniejsze gotowe. Sensowne kolejne kroki – wszystko można później zmienić.",
