  "Deine Termine (und die deiner Kinder) sowie die Vereinstermine erscheinen automatisch in deinem Kalender – Änderungen und Absagen inklusive. Teilnehmerlisten werden nicht übertragen.": "Twoje terminy (i terminy twoich dzieci) oraz terminy klubu pojawiają się automatycznie w twoim kalendarzu – razem ze zmianami i odwołaniami. Listy uczestników nie są przesyłane.",
