  "Der Kassenstand geht mit in die Nachfolgemannschaft": "Saldo przechodzi do drużyny następczyni",
  "Der Kassenwart bucht Einnahmen, Ausgaben und Einzahlungen und pflegt den Strafenkatalog – gemeinsam mit dem Trainerteam. Infrage kommen Mitglieder mit eigenem Login und Eltern.": "Skarbnik księguje przychody, wydatki i wpłaty oraz prowadzi taryfikator kar – razem ze sztabem szkoleniowym. Wchodzą w grę członkowie z własnym loginem i rodzice.",
  "Der Kassenwart bucht und verwaltet Beiträge, Kassenprüfer sehen alles und prüfen am Jahresende. Optional – Rollen lassen sich später vergeben.": "Skarbnik księguje i zarządza składkami, kontrolerzy kasy widzą wszystko i kontrolują na koniec roku. Opcjonalnie – role można nadać później.",
