  "Der Schiedsrichter": "Sędzia",
  "Der Spielbericht ist erst nach Anpfiff möglich.": "Sprawozdanie z meczu jest możliwe dopiero po rozpoczęciu meczu.",
  "Der Spielbericht konnte nicht gespeichert werden.": "Nie udało się zapisać sprawozdania z meczu.",
