  "Der Spielerbedarf wurde zurückgezogen – du musst nicht aushelfen.": "Zapotrzebowanie na zawodników zostało wycofane – nie musisz pomagać.",
  "Der Sponsor": "Sponsor",
  "Der Standard-Treffpunkt und die Minuten vor Beginn werden bei neuen Terminen vorbelegt.": "Domyślne miejsce zbiórki i minuty przed rozpoczęciem są wstępnie wypełniane w nowych terminach.",
