  "Der Termin": "Termin",
  "Der Termin gehört nicht zu dieser Mannschaft.": "Termin nie należy do tej drużyny.",
  "Der Termin gehört nicht zur Mannschaft.": "Termin nie należy do drużyny.",
  "Der Termin hat schon begonnen.": "Termin już się rozpoczął.",
  "Der Termin ist bereits abgesagt.": "Termin został już odwołany.",
  "Der Termin konnte nicht abgesagt werden.": "Nie udało się odwołać terminu.",
  "Der Termin konnte nicht angelegt werden.": "Nie udało się utworzyć terminu.",
  "Der Termin liegt in der Vergangenheit.": "Termin jest w przeszłości.",
  "Der Termin wurde abgesagt.": "Termin został odwołany.",
  "Der Untergrund je Platz hilft bei der Planung, z. B. wenn Rasenplätze gesperrt sind.": "Nawierzchnia każdego boiska pomaga w planowaniu, np. gdy boiska trawiaste są zablokowane.",
  "Der Verband setzt dich bei fremden Spielen ein. Trage den Einsatz hier ein, damit er in deinem Kalender steht und Überschneidungen mit deinen Terminen auffallen.": "Związek wyznacza cię do meczów innych drużyn. Wpisz tu dyżur, aby był w twoim kalendarzu i aby zauważyć nakładanie się z twoimi terminami.",
  "Der Verein braucht mindestens einen Fulladmin.": "Klub potrzebuje co najmniej jednego pełnego administratora.",
  "Der Verein ist bereits eingerichtet.": "Klub jest już skonfigurowany.",
  "Der Verein kann mehrere Kassen führen, z. B. eine Jugendkasse. Unter „Admin-Verwaltung → Verein → Abteilungen“ legst du Abteilungen an (z. B. Senioren, Frauen, Jugend); danach fragt die App, ob die Abteilung eine eigene Kasse bekommen soll. Unter „Kassen“ legst du Kassen an, ordnest sie einer oder mehreren Abteilungen zu und bestimmst genau eine Hauptkasse. Ohne eigene Kasse laufen die Buchungen einer Abteilung über die Hauptkasse. Jede Kasse hat eigene Konten und Beiträge; in der Vereinskasse wechselst du oben zwischen „Alle“ und einer einzelnen Kasse. Kassen werden nie gelöscht, nur stillgelegt. Eine Umbuchung zwischen Konten verschiedener Kassen wird in beiden Kassen gebucht, ein Storno wirkt in beiden. Die Rolle Kassenwart (Verein) kann für den ganzen Verein oder nur für eine Abteilung vergeben werden und gilt dann nur für deren Kassen.": "Klub może prowadzić kilka kas, np. kasę młodzieżową. W „Administracja → Klub → Sekcje“ tworzysz sekcje (np. seniorzy, kobiety, młodzież); potem aplikacja pyta, czy sekcja ma dostać własną kasę. W „Kasy“ tworzysz kasy, przypisujesz je do jednej lub kilku sekcji i wyznaczasz dokładnie jedną kasę główną. Bez własnej kasy księgowania sekcji idą przez kasę główną. Każda kasa ma własne konta i składki; w kasie klubu przełączasz się u góry między „Wszystkie“ a pojedynczą kasą. Kas nigdy się nie usuwa, tylko wyłącza. Przeksięgowanie między kontami różnych kas jest księgowane w obu kasach, storno działa w obu. Rolę skarbnika (klub) można nadać dla całego klubu lub tylko dla jednej sekcji i wtedy dotyczy tylko jej kas.",
  "Der Verein verlangt für deine Rolle die 2-Faktor-Anmeldung.": "Klub wymaga dla twojej roli logowania dwuskładnikowego.",
  "Der Verein verlangt für die Verwaltung die 2-Faktor-Anmeldung. Bitte unter „Konto & Sicherheit“ einrichten.": "Klub wymaga dla administracji logowania dwuskładnikowego. Skonfiguruj je w „Konto i bezpieczeństwo“.",
  "Der Verein verlangt sie für deine Verwaltungsrechte. Bis dahin ist die Verwaltung gesperrt.": "Klub wymaga jej dla twoich uprawnień administracyjnych. Do tego czasu administracja jest zablokowana.",
  "Der Verein verlangt zu jeder Auslage einen Beleg. Bitte füge ein Foto oder eine Datei hinzu.": "Klub wymaga paragonu do każdego wydatku. Dodaj zdjęcie lub plik.",
  "Der Vermerk": "Adnotacja",
  "Der Vermerk wird entfernt.": "Adnotacja zostanie usunięta.",
  "Der Verwendungszweck fehlt.": "Brakuje tytułu płatności.",
  "Der volle Name steht auf Dokumenten, der Kurzname in der Kopfzeile und auf dem Wappen.": "Pełna nazwa jest na dokumentach, skrócona w nagłówku i na herbie.",
  "Der Vorstand sieht – wenn der Verein es in „Einsicht“ freigibt – unter „Verein → Vereinsleben → Kassenübersicht“ eine reine Anzeige: Kassenstand gesamt, Einnahmen und Ausgaben, die einzelnen Kassen und die Beitragsquote. Buchungen, Belege und Funktionen gibt es dort nicht; die Vereinskasse selbst führen Kassenwart und Kassenprüfer.": "Zarząd widzi – jeśli klub włączy to w „Wgląd“ – w „Klub → Życie klubowe → Przegląd kas“ widok tylko do odczytu: łączny stan kas, przychody i wydatki, poszczególne kasy i wskaźnik opłacenia składek. Księgowań, dowodów i funkcji tam nie ma; kasę klubu prowadzą skarbnik i kontrolerzy kasy.",
  "Der Vorstand sieht auch Kassenbuch und Belege (ohne zu buchen)": "Zarząd widzi także księgę kasową i dowody (bez księgowania)",
  "Der Vorstand sieht Kontostände und Summen, aber keine einzelnen Buchungen": "Zarząd widzi stany kont i sumy, ale nie poszczególne księgowania",
