  "Der Zuschuss": "Dopłata",
  "Der Zuschuss steht als Ausgabe im Kassenbuch und zugleich als Einnahme in der Mannschaftskasse. Danach kann er nicht mehr einzeln storniert werden.": "Dopłata widnieje jako wydatek w księdze kasowej i jednocześnie jako przychód w kasie drużyny. Potem nie można jej anulować osobno.",
