  "Die Einstellung gilt für alle Mannschaften der Abteilung. Ist ein Modul hier aus, kann es keine Mannschaft darin einschalten. „Wie Verein“ übernimmt die Vereinseinstellung.": "Ustawienie dotyczy wszystkich drużyn sekcji. Jeśli moduł jest tu wyłączony, żadna drużyna w niej nie może go włączyć. „Jak klub“ przejmuje ustawienie klubu.",
  "Die Einstellung gilt nur auf diesem Gerät.": "Ustawienie dotyczy tylko tego urządzenia.",
