  "Die Ergebnisse sind für alle sichtbar.": "Wyniki są widoczne dla wszystkich.",
  "Die erste Zeile braucht mindestens die Spalten „Vorname“ und „Nachname“.": "Pierwszy wiersz wymaga co najmniej kolumn „Imię“ i „Nazwisko“.",
  "Die erste Zeile enthält die Spaltenüberschriften. Die Zuordnung zu den Feldern prüfst du im nächsten Schritt.": "Pierwszy wiersz zawiera nagłówki kolumn. Przypisanie do pól sprawdzisz w następnym kroku.",
  "Die Excel-Datei lässt sich nicht lesen.": "Pliku Excela nie można odczytać.",
  "Die Farbe änderst du später jederzeit unter Verwaltung › Verein & Design.": "Kolor możesz później w każdej chwili zmienić w Administracja › Klub i wygląd.",
