  "Die Frist für Korrekturen ({0} Tage) ist abgelaufen. Die Anwesenheit ändert jetzt nur noch der Admin.": "Termin na korekty ({0} dni) minął. Obecność może teraz zmienić już tylko administrator.",
  "Die Frist für Korrekturen ist abgelaufen – nur der Admin kann die Anwesenheit noch ändern.": "Termin na korekty minął – obecność może jeszcze zmienić tylko administrator.",
  "Die Frist für Zu- und Absagen ist abgelaufen. Bitte wende dich an dein Trainerteam.": "Termin na potwierdzenia i odwołania minął. Zwróć się do swojego sztabu szkoleniowego.",
  "Die Frist ist am {0}, {1} Uhr abgelaufen. Bei Änderungen wende dich an dein Trainerteam.": "Termin minął {0}, {1}. W sprawie zmian zwróć się do swojego sztabu szkoleniowego.",
