  "Die gemeldete Zahlung über {0} ist noch nicht angekommen. Bitte wende dich an die Kasse.": "Zgłoszona płatność na kwotę {0} jeszcze nie dotarła. Zwróć się do kasy.",
  "Die gesetzliche Aufbewahrungsfrist läuft noch.": "Ustawowy okres przechowywania jeszcze trwa.",
  "Die Hauptkasse kann nicht stillgelegt werden. Lege zuerst eine andere Kasse als Hauptkasse fest.": "Kasy głównej nie można wyłączyć. Najpierw ustaw inną kasę jako główną.",
  "Die Hauptkasse nimmt Buchungen ohne Abteilungsbezug auf und kann nicht stillgelegt werden. Lege eine andere Kasse als Hauptkasse fest, um zu wechseln.": "Kasa główna przyjmuje księgowania bez przypisania do sekcji i nie można jej wyłączyć. Ustaw inną kasę jako główną, aby zmienić.",
  "Die importierten Einträge wurden wieder entfernt, aktualisierte Werte zurückgesetzt.": "Zaimportowane wpisy zostały usunięte, zaktualizowane wartości przywrócone.",
  "Die Kaderliste ist für dich nicht freigegeben.": "Lista kadry nie jest dla ciebie udostępniona.",
  "Die Kasse": "Kasa",
  "Die Kasse bestätigt den Eingang – erst dann ist dein Konto ausgeglichen.": "Kasa potwierdza wpływ – dopiero wtedy twoje konto jest wyrównane.",
  "Die Kasse ist stillgelegt.": "Kasa jest wyłączona.",
  "Die Kasse konnte nicht vollständig eingerichtet werden.": "Nie udało się w pełni skonfigurować kasy.",
