  "Die Kassenprüfung machen Kassenprüfer.": "Kontrolę kasy wykonują kontrolerzy kasy.",
  "Die Kassenprüfung machen Kassenprüfer. Hier siehst du die abgegebenen Prüfberichte.": "Kontrolę kasy wykonują kontrolerzy kasy. Tu widzisz złożone raporty z kontroli.",
  "Die Kassenstatistik sieht die Mannschaft.": "Statystykę kasy widzi drużyna.",
  "Die Kassenverwaltung ist für Kassenwart und Trainerteam.": "Zarządzanie kasą jest dla skarbnika i sztabu szkoleniowego.",
  "Die Kategorie": "Kategoria",
  "Die Kategorie „{0}“ gilt für Ausgaben.": "Kategoria „{0}“ dotyczy wydatków.",
  "Die Kategorie „{0}“ gilt für Einnahmen.": "Kategoria „{0}“ dotyczy przychodów.",
  "Die Kategorie ist archiviert.": "Kategoria jest zarchiwizowana.",
  "Die Kennzahl zeigt auf einen Blick, was dort los ist: bei Terminen und Veranstaltungen das Datum des nächsten (TT.MM.), beim Kader die Zahl der Spieler, bei der Statistik die Bilanz (Siege-Remis-Niederlagen), bei der Kasse den Kassenstand, bei Aufgaben und Umfragen die offenen, bei News, Dokumenten und Wissen die neuen, beim Spielplan die Spiele der Woche, bei Helfern die freien Plätze. Orange heißt: Hier wartet etwas auf dich. Kacheln ohne sinnvolle Zahl haben keine Kennzahl.": "Wskaźnik pokazuje na pierwszy rzut oka, co się tam dzieje: przy terminach i wydarzeniach datę najbliższego (DD.MM.), przy kadrze liczbę zawodników, przy statystyce bilans (zwycięstwa-remisy-porażki), przy kasie stan kasy, przy zadaniach i ankietach otwarte, przy aktualnościach, dokumentach i wiedzy nowe, przy terminarzu mecze tygodnia, przy pomocnikach wolne miejsca. Pomarańczowy oznacza: coś na ciebie czeka. Kafelki bez sensownej liczby nie mają wskaźnika.",
  "Die kleine Zeile unter dem Namen einer Kachel zeigt, was für dich gerade wichtig ist, z. B. „Du hast 12,50 € offen“, „Antwort fehlt“ oder „2 zur Freigabe“. Die Farbe verstärkt den Text: Orange heißt, es gibt etwas zu tun. Was du nicht sehen darfst, wird nicht angezeigt.": "Mały wiersz pod nazwą kafelka pokazuje, co jest teraz dla ciebie ważne, np. „Masz do zapłaty 12,50 €“, „Brak odpowiedzi“ lub „2 do zatwierdzenia“. Kolor wzmacnia tekst: pomarańczowy oznacza, że jest coś do zrobienia. Czego nie możesz zobaczyć, nie jest wyświetlane.",
  "Die Kostenstelle": "Miejsce powstawania kosztów",
  "Die Lesebestätigung sehen Verfasser und Freigebende.": "Potwierdzenie odczytu widzą autorzy i osoby zatwierdzające.",
