  "Eine Mannschaft ist eine Gruppe mit eigenem Kader, eigenen Terminen und eigenen Regeln – zum Beispiel „B-Jugend“ oder „1. Herren“. Alles lässt sich später ändern.": "Drużyna to grupa z własną kadrą, własnymi terminami i własnymi zasadami – na przykład „B-Jugend“ lub „1. drużyna seniorów“. Wszystko można później zmienić.",
