  "Einzahlungsweg": "Sposób wpłaty",
  "Einzeln unter „Mitglieder → Mitglied anlegen“ oder per Import aus Excel oder CSV („Importieren“): Bereich wählen, Vorlage laden, Datei hochladen, Spalten zuordnen, Vorschau prüfen (neu, aktualisiert, Dublette, Fehler), bei Dubletten überspringen, aktualisieren oder neu anlegen. Der Import wird ganz oder gar nicht übernommen und lässt sich 24 Stunden lang rückgängig machen. Austritte beenden Mannschaftszugehörigkeiten und sperren den App-Zugang. In der Mitgliederliste filterst du nach Rolle, Trainerteam, individuellen Rechten oder fehlendem App-Zugang.": "Pojedynczo w „Członkowie → Utwórz członka“ lub przez import z Excela albo CSV („Importuj“): wybierz obszar, pobierz szablon, wgraj plik, przypisz kolumny, sprawdź podgląd (nowi, zaktualizowani, duplikat, błąd), przy duplikatach pomiń, zaktualizuj lub utwórz na nowo. Import jest przejmowany w całości albo wcale i można go cofnąć przez 24 godziny. Wystąpienia kończą przynależność do drużyn i blokują dostęp do aplikacji. Na liście członków filtrujesz wg roli, sztabu szkoleniowego, uprawnień indywidualnych lub braku dostępu do aplikacji.",
  "Einzelne Personen einladen dürfen nur Berechtigte.": "Pojedyncze osoby mogą zapraszać tylko uprawnieni.",
