  "Eltern, die mit ihrem Kind verknüpft sind, antworten für das Kind und sehen dessen Termine. Ohne Verknüpfung sagt niemand für das Kind zu.": "Rodzice powiązani z dzieckiem odpowiadają za dziecko i widzą jego wydarzenia. Bez powiązania nikt nie odpowiada za dziecko.",
