  "Empfohlene Reihenfolge: zuerst die Mitglieder, dann Mannschaften und Kader, zuletzt Termine und Kasse – so findet jeder Import seine Personen und Mannschaften wieder.": "Zalecana kolejność: najpierw członkowie, potem drużyny i kadry, na końcu terminy i kasa – dzięki temu każdy import odnajdzie swoje osoby i drużyny.",
