  "Erinnerung vor der Frist (Stunden, 0 = keine)": "Przypomnienie przed terminem (godziny, 0 = brak)",
  "Erinnerung, Bezahlinfos und Kassenprüfung?": "Przypomnienia, informacje o płatnościach i kontrola kasy?",
  "Erinnerungen": "Przypomnienia",
  "Erinnerungen an offene Beträge verschickst du per Knopf oder lässt sie monatlich automatisch laufen (Einstellungen). Unter „Bezahlinfos & Einstellungen“ hinterlegst du IBAN und PayPal und bestimmst, ob alle die Beträge aller Beteiligten sehen (Standard: jeder nur die eigenen; Kassenstand, Einnahmen und Ausgaben sieht immer die ganze Mannschaft). „Kassenprüfung“ hält den Stand mit Prüfer fest. Berichte gibt es als Excel und PDF.": "Przypomnienia o zaległych kwotach wysyłasz przyciskiem lub pozwalasz im działać automatycznie co miesiąc (Ustawienia). W „Informacje o płatnościach i ustawienia“ zapisujesz IBAN i PayPal oraz decydujesz, czy wszyscy widzą kwoty wszystkich uczestników (domyślnie: każdy tylko własne; stan kasy, przychody i wydatki zawsze widzi cała drużyna). „Kontrola kasy“ zapisuje stan wraz z kontrolerem. Raporty są dostępne jako Excel i PDF.",
  "Erklärung": "Objaśnienie",
  "Erlaubt sind PDF, Word (.docx), Excel (.xlsx), JPG und PNG.": "Dozwolone są PDF, Word (.docx), Excel (.xlsx), JPG i PNG.",
