  "Es erscheint oben in der App bei allen Mitgliedern. Ohne Logo zeigt die App ein Wappen mit dem Kürzel.": "Pojawia się u góry aplikacji u wszystkich członków. Bez logo aplikacja pokazuje herb ze skrótem.",
  "Es fehlen {0} aktive Schiedsrichter": "Brakuje aktywnych sędziów: {0}",
  "Es fehlen zugeordnete Pflichtfelder.": "Brakuje przypisanych pól obowiązkowych.",
  "Es gab nichts zu übernehmen.": "Nie było nic do przejęcia.",
  "Es gibt {0} neue Funktionen": "Nowych funkcji: {0}",
  "Es gibt 1 neue Funktion": "Jest 1 nowa funkcja",
  "Es gibt bereits Kategorien.": "Kategorie już istnieją.",
  "Es gibt keine Einnahmekategorie für Beiträge. Lege sie in der Vereinskasse an.": "Brak kategorii przychodu dla składek. Utwórz ją w kasie klubu.",
  "Es gibt keine neuen Mitglieder zu übernehmen.": "Nie ma nowych członków do przejęcia.",
  "Es gibt nichts zu übernehmen.": "Nie ma nic do przejęcia.",
  "Es gibt noch fehlerhafte Zeilen. Bitte korrigieren oder abwählen.": "Są jeszcze błędne wiersze. Popraw je lub odznacz.",
  "Es gibt noch keine Erwachsenen mit Login in der Mannschaft.": "W drużynie nie ma jeszcze dorosłych z loginem.",
  "Es gibt noch keine Kategorien für diese Art. Lege sie unter „Einrichtung“ an.": "Nie ma jeszcze kategorii dla tego rodzaju. Utwórz je w „Konfiguracja“.",
  "Es gibt nur einen Fulladmin – lege einen zweiten an.": "Jest tylko jeden pełny administrator – dodaj drugiego.",
  "Es gibt zwei Wege: Unter „Ich“ stehen direkt unter deinem Profil die zwei farbigen Knöpfe „Admin-Verwaltung“ (violett) und „Vereinskasse“ (blau) – nur die, für die du Rechte hast. Außerdem steht unter „Verein“ in der Gruppe „Meine Vereinsaufgaben“ der Zugang zur „Verwaltung“ (für alle mit Verwaltungsrechten) und zur „Vereinskasse“ (für alle mit Kassenzugriff); am Desktop stehen beide dauerhaft in der Seitenleiste. Beide öffnen einen eigenen Bereich mit farbigem Kopfband und „Zur App“ oben sowie einer Leiste mit Reitern unten. Die Verwaltung hat die Reiter Übersicht, Mitglieder, Sport, Inhalte und Verein – du siehst nur, wofür du Rechte hast. In der Vereinskasse gibt es Übersicht, Buchung, Beiträge, Planung und Auswertung. Funktionen mit „Bald verfügbar“ folgen in einem späteren Update.": "Są dwie drogi: w „Ja“ tuż pod twoim profilem są dwa kolorowe przyciski „Administracja“ (fioletowy) i „Kasa klubu“ (niebieski) – tylko te, do których masz uprawnienia. Ponadto w „Klub“ w grupie „Moje zadania klubowe“ jest dostęp do „Administracji“ (dla wszystkich z uprawnieniami administracyjnymi) i do „Kasy klubu“ (dla wszystkich z dostępem do kasy); na komputerze oba są na stałe w panelu bocznym. Oba otwierają osobny obszar z kolorowym nagłówkiem i „Do aplikacji“ u góry oraz paskiem z zakładkami na dole. Administracja ma zakładki Przegląd, Członkowie, Sport, Treści i Klub – widzisz tylko to, do czego masz uprawnienia. W kasie klubu są Przegląd, Księgowanie, Składki, Planowanie i Zestawienia. Funkcje z „Wkrótce dostępne“ pojawią się w późniejszej aktualizacji.",
  "Es ist ein unerwarteter Fehler aufgetreten.": "Wystąpił nieoczekiwany błąd.",
  "Es ist keine laufende Saison eingerichtet.": "Nie ustawiono bieżącego sezonu.",
  "Es muss immer eine Hauptkasse geben. Lege eine andere Kasse als Hauptkasse fest.": "Zawsze musi istnieć kasa główna. Ustaw inną kasę jako główną.",
  "Es sind noch {0} Stichproben offen.": "Otwartych próbek: {0}.",
  "Es sind noch {0} Stichproben offen. Bitte alle abhaken oder beanstanden.": "Otwartych próbek: {0}. Odhacz wszystkie lub zgłoś zastrzeżenia.",
  "Es sind nur noch {0} offen. Zu viel Gezahltes bitte als eigene Einnahme buchen.": "Do zapłaty zostało tylko {0}. Nadpłatę zaksięguj jako osobny przychód.",
