  "Feste Gruppen müssen nicht ständig antworten – „Automatisch zugesagt“ spart Nachfragen und zeigt trotzdem, wer fehlt. Bei Spielen ist die aktive Antwort oft sinnvoller, weil der Kader begrenzt ist.": "Stałe grupy nie muszą stale odpowiadać – „Automatycznie potwierdzone” oszczędza dopytywania i nadal pokazuje, kogo brakuje. Przy meczach aktywna odpowiedź ma często więcej sensu, bo kadra jest ograniczona.",
