  "Für wen?": "Dla kogo?",
  "Für Zuwendungsbestätigungen braucht der Verein Angaben aus dem Freistellungsbescheid. Das trägt die Vereinsadministration ein; die Vorlage wird erst nach rechtlicher Prüfung freigegeben.": "Do potwierdzeń darowizn klub potrzebuje danych z decyzji o zwolnieniu. Wpisuje je administracja klubu; szablon jest zatwierdzany dopiero po kontroli prawnej.",
  "Fuß: {0}": "Noga: {0}",
  "Ganz unten auf Start findest du den Schnellzugriff – Abkürzungen zu Seiten, die du oft brauchst. Tippe auf „Hinzufügen“, wähle die Einträge aus und speichere. „Zurücksetzen“ stellt die Voreinstellung für deine Rolle wieder her. Die Auswahl gilt auf allen deinen Geräten.": "Na samym dole strony głównej znajdziesz szybki dostęp – skróty do stron, których często potrzebujesz. Dotknij „Dodaj“, wybierz pozycje i zapisz. „Resetuj“ przywraca ustawienie domyślne dla twojej roli. Wybór obowiązuje na wszystkich twoich urządzeniach.",
