  "Gehört das Geld dem Verein, muss es in dessen Büchern auftauchen. Klärt das bitte mit dem Kassenwart des Vereins.": "Jeśli pieniądze należą do klubu, muszą być w jego księgach. Wyjaśnijcie to ze skarbnikiem klubu.",
