  "Gelesen": "Przeczytane",
  "Gelöscht – lässt sich wiederherstellen": "Usunięto – można przywrócić",
  "Gelöschte Einträge liegen hier und lassen sich wiederherstellen. Endgültig gelöscht wird nie automatisch, sondern nur auf deinen Anstoß.": "Usunięte wpisy są tutaj i można je przywrócić. Trwałe usunięcie nigdy nie następuje automatycznie, tylko z twojej inicjatywy.",
  "Gelöschte Rollen": "Usunięte role",
  "Gelöschte Rollen lassen sich wiederherstellen.": "Usunięte role można przywrócić.",
  "Gelöschte Wissensartikel, Übungen, Aufgaben, Sponsoren, Dokumente und ausgemustertes Material landen im Archiv; bei Dokumenten bleibt die Datei erhalten, bis das Archiv bereinigt wird. Das Trainerteam öffnet das Archiv seiner Mannschaft unter „Team → Archiv“ (gelöschte Aufgaben und Dokumente, wiederherstellen). Die Administration öffnet das ganze Archiv unter „Verwaltung → Abo & Kontrolle → Archiv“: Dort stellst du einen Eintrag mit „Wiederherstellen“ wieder her. Ist sein Name inzwischen vergeben, fragt dich die App nach einem neuen Namen. Endgültig gelöscht wird nie automatisch: „Bereinigen“ entfernt, was älter als die Standardfrist ist (derzeit 2 Jahre), „Archiv leeren“ löscht alles; beides nur auf deinen Anstoß und mit Bestätigung. „Archiv exportieren“ speichert alle archivierten Einträge als Datei.": "Usunięte artykuły wiedzy, ćwiczenia, zadania, sponsorzy, dokumenty i wycofany sprzęt trafiają do archiwum; w przypadku dokumentów plik zostaje, dopóki archiwum nie zostanie oczyszczone. Sztab szkoleniowy otwiera archiwum swojej drużyny w „Zespół → Archiwum“ (usunięte zadania i dokumenty, przywracanie). Administracja otwiera całe archiwum w „Administracja → Subskrypcja i kontrola → Archiwum“: tam przywracasz wpis przez „Przywróć“. Jeśli jego nazwa jest już zajęta, aplikacja zapyta o nową. Trwałe usunięcie nigdy nie następuje automatycznie: „Oczyść“ usuwa to, co jest starsze niż domyślny okres (obecnie 2 lata), „Opróżnij archiwum“ usuwa wszystko; oba tylko z twojej inicjatywy i po potwierdzeniu. „Eksportuj archiwum“ zapisuje wszystkie zarchiwizowane wpisy jako plik.",
  "Gemeinnützig": "Pożytku publicznego",
  "Gemeinnützige Vereine müssen Einnahmen und Ausgaben steuerlich trennen. Ist der Verein nicht gemeinnützig, reicht eine einfachere Kategorieliste.": "Kluby pożytku publicznego muszą rozdzielać przychody i wydatki podatkowo. Jeśli klub nie jest pożytku publicznego, wystarczy prostsza lista kategorii.",
