  "Gib den 6-stelligen Code aus deiner Authenticator-App ein – oder einen deiner Wiederherstellungscodes.": "Wpisz 6-cyfrowy kod z aplikacji uwierzytelniającej – lub jeden z kodów odzyskiwania.",
  "Gib den Einladungscode ein oder füge den Link aus deiner Einladung ein. Du bekommst ihn von deinem Verein per E-Mail, Nachricht oder als QR-Code.": "Wpisz kod zaproszenia lub wklej link z zaproszenia. Dostaniesz go od swojego klubu e-mailem, wiadomością lub jako kod QR.",
