  "Hallo {0},\n\ndeine Anfrage für {1} wurde freigegeben. Du kannst dich jetzt in der App anmelden:\n\n{2}": "Cześć {0},\n\ntwoja prośba dla {1} została zatwierdzona. Możesz się teraz zalogować w aplikacji:\n\n{2}",
  "Hallo {0},\n\ndeine Anfrage für {1} wurde leider nicht freigegeben.{2}": "Cześć {0},\n\ntwoja prośba dla {1} niestety nie została zatwierdzona.{2}",
  "Hallo, {0}": "Cześć, {0}",
  "Hallo, Maximilian-Alexander von Hohenzollern-Sigmaringen": "Cześć, Maximilian-Alexander von Hohenzollern-Sigmaringen",
  "Hallo! Wir nutzen Clubroof für {0}: Termine, Zu- und Absagen und alle Infos an einem Ort. Hier kommst du in die Mannschaft: {1}": "Cześć! Używamy Clubroof dla {0}: terminy, potwierdzenia i odwołania oraz wszystkie informacje w jednym miejscu. Tu dołączysz do drużyny: {1}",
  "Hält den Kassenstand von heute fest – z. B. nach der Kassenprüfung oder zum Saisonende. Der Abschluss erscheint auch im Kassenbericht. Beim Saisonwechsel geht die Kasse automatisch auf die neue Mannschaft über.": "Zapisuje dzisiejszy stan kasy – np. po kontroli kasy lub na koniec sezonu. Zamknięcie pojawia się także w raporcie kasowym. Przy zmianie sezonu kasa automatycznie przechodzi na nową drużynę.",
  "Halte die Kamera auf den QR-Code deiner Einladung.": "Skieruj aparat na kod QR ze swojego zaproszenia.",
  "Hartplatz": "Boisko twarde",
  "Hat eine Abteilung eigenes Geld (z. B. die Jugend), bekommt sie eine eigene Kasse. Wer die Abteilung leitet, sieht dann nur diese Kasse. Optional.": "Jeśli sekcja ma własne pieniądze (np. młodzież), dostaje własną kasę. Kierujący sekcją widzi wtedy tylko tę kasę. Opcjonalnie.",
