  "Hier findest du alles, womit du selbst bestimmst, wer was von dir sieht und wie die App dich erreicht.": "Tu znajdziesz wszystko, czym sam(a) decydujesz, kto co o tobie widzi i jak aplikacja się z tobą kontaktuje.",
