  "Ich": "Ja",
  "Ich bin im Urlaub oder verletzt. Muss ich jeden Termin absagen?": "Jestem na urlopie lub kontuzjowany(-a). Czy muszę odwoływać każdy termin?",
  "Ich bin Schiedsrichter – wo trage ich meine Einsätze ein?": "Jestem sędzią – gdzie wpisuję swoje dyżury?",
