  "Je Spiel: die Nummer wird bei jeder Aufstellung neu vergeben. Fest: eine Nummer pro Spieler für die ganze Saison.": "Na mecz: numer jest nadawany na nowo przy każdym składzie. Stały: jeden numer na zawodnika na cały sezon.",
  "Je Sponsor": "Wg sponsorów",
  "Jede Änderung setzt die Freigabe der Vorlage zurück.": "Każda zmiana cofa zatwierdzenie szablonu.",
  "Jede Kasse hat eigene Konten, Beiträge und Auswertung. Ohne Zuordnung läuft eine Abteilung über die Hauptkasse. Der Jahresabschluss gilt immer für den ganzen Verein.": "Każda kasa ma własne konta, składki i zestawienia. Bez przypisania sekcja działa przez kasę główną. Zamknięcie roku zawsze dotyczy całego klubu.",
  "Jede Leitung sieht nur Daten ihrer Abteilung": "Każde kierownictwo widzi tylko dane swojej sekcji",
  "Jede Mannschaft legt fest, bis wann Zu- und Absagen möglich sind. Der Countdown steht am Termin („Frist: Noch 2 Tage“). Danach bleibt deine Antwort sichtbar (Schloss „Frist abgelaufen“), ändern kann sie nur dein Trainerteam.": "Każda drużyna ustala, do kiedy można potwierdzać i odwoływać. Odliczanie jest przy terminie („Termin: jeszcze 2 dni“). Potem twoja odpowiedź pozostaje widoczna (kłódka „Termin minął“), zmienić ją może tylko twój sztab szkoleniowy.",
  "Jede Person sagt zu oder ab – der Trainer sieht, wer noch fehlt": "Każda osoba potwierdza lub odwołuje – trener widzi, kogo jeszcze brakuje",
  "Jede Zeile ist grün (neu), blau (aktualisiert), gelb (Dublette) oder rot (Fehler). Abgewählte Zeilen werden nicht übernommen.": "Każdy wiersz jest zielony (nowy), niebieski (zaktualizowany), żółty (duplikat) lub czerwony (błąd). Odznaczone wiersze nie są przejmowane.",
  "Jeder Spieler behält seine Nummer; sie erscheint im Kader und in der Aufstellung.": "Każdy zawodnik zachowuje swój numer; pojawia się w kadrze i w składzie.",
  "Jeder Spieler der Startelf braucht einen Platz der Formation.": "Każdy zawodnik pierwszego składu potrzebuje miejsca w ustawieniu.",
  "Jedes Feld kann nur einer Spalte zugeordnet werden.": "Każde pole można przypisać tylko do jednej kolumny.",
  "Jedes Mitglied reicht unter „Verein → Auslage einreichen“ Kosten mit Beleg (Foto) oder Fahrtkosten ein – bei Fahrtkosten rechnet die App aus den Kilometern (30 Cent je km). Der Kassenwart sieht die Auslagen unter „Vereinskasse → Buchung → Auslagen“, genehmigt oder lehnt mit Begründung ab und erstattet: Dabei entsteht eine Ausgabe im Kassenbuch. Du bekommst zu jedem Schritt eine Benachrichtigung. Eine erstattete Auslage kann nicht storniert werden.": "Każdy członek składa w „Klub → Złóż wniosek o zwrot kosztów“ koszty z dowodem (zdjęcie) lub koszty przejazdu – przy kosztach przejazdu aplikacja przelicza z kilometrów (30 centów za km). Skarbnik widzi wnioski w „Kasa klubu → Księgowanie → Zwroty kosztów“, zatwierdza lub odrzuca z uzasadnieniem i zwraca: powstaje wtedy wydatek w księdze kasowej. Przy każdym kroku dostajesz powiadomienie. Zrealizowanego zwrotu kosztów nie można anulować.",
