  "Kassenprüfer": "Kontroler kasy",
  "Kassenprüfer beginnen unter „Vereinskasse → Auswertung → Kassenprüfung“ eine Prüfung für ein Jahr – für den ganzen Verein oder nur für ihre Kasse. Die App zieht auf Wunsch zufällige Stichproben; jede Buchung wird abgehakt oder mit Begründung beanstandet, den Beleg siehst du direkt. Dazu kommen freie Vermerke. Sind alle Stichproben erledigt, gibst du den Prüfbericht mit deinem Ergebnis ab; danach ist er nicht mehr änderbar und dient als Grundlage der Entlastung. Die Kassenführung sieht abgegebene Berichte (auch als PDF oder CSV). Prüfer buchen nicht, der Kassenwart prüft nicht.": "Kontrolerzy kasy rozpoczynają w „Kasa klubu → Zestawienia → Kontrola kasy“ kontrolę za dany rok – dla całego klubu lub tylko dla swojej kasy. Aplikacja na życzenie losuje próbki; każde księgowanie jest odhaczane lub kwestionowane z uzasadnieniem, dowód widzisz od razu. Do tego dochodzą dowolne adnotacje. Gdy wszystkie próbki są załatwione, składasz raport z kontroli ze swoim wynikiem; potem nie można go już zmienić i służy jako podstawa absolutorium. Zarząd kasy widzi złożone raporty (także jako PDF lub CSV). Kontrolerzy nie księgują, skarbnik nie kontroluje.",
