  "Kassenstand, Einnahmen und Ausgaben sieht immer die ganze Mannschaft. Die Beträge der einzelnen Personen zeigst du nur, wenn ihr das wollt – sonst sieht jeder nur die eigenen.": "Stan kasy, przychody i wydatki zawsze widzi cała drużyna. Kwoty poszczególnych osób pokazujesz tylko, jeśli tego chcecie – inaczej każdy widzi tylko własne.",
