  "Kurzfristige Absagen und dringende Vereinsnews erreichen dich unabhängig von diesen Einstellungen – auch in der Ruhezeit.": "Odwołania w ostatniej chwili i pilne aktualności klubowe docierają do ciebie niezależnie od tych ustawień – także w czasie ciszy.",
