  "Lade Daten als Excel- oder CSV-Datei herunter. Du siehst nur, wofür du Rechte hast; jeder Export wird im Protokoll des Vereins festgehalten.": "Pobierz dane jako plik Excel lub CSV. Widzisz tylko to, do czego masz uprawnienia; każdy eksport jest zapisywany w dzienniku klubu.",
  "Lade den Kontoauszug als CSV-Datei deiner Bank hoch. Erkannt werden Buchungstag, Betrag, Name und Verwendungszweck. Zugeordnet wird per Mitgliedsnummer oder Name, wenn der Betrag genau zu einer offenen Forderung passt. Du siehst alles vorher.": "Wgraj wyciąg bankowy jako plik CSV z twojego banku. Rozpoznawane są data księgowania, kwota, nazwa i tytuł płatności. Przypisanie następuje po numerze członkowskim lub nazwisku, jeśli kwota dokładnie pasuje do otwartej należności. Wszystko widzisz wcześniej.",
  "Lade den Spielplan als CSV-Datei aus dem DFBnet (Meisterschaft › Vereinsspielplan bzw. Mannschaftsspielplan › Export). Du siehst zuerst eine Vorschau – übernommen wird erst nach deiner Bestätigung. Ein erneuter Import aktualisiert bestehende Spiele, statt sie doppelt anzulegen.": "Wgraj terminarz jako plik CSV z DFBnet (Rozgrywki › Terminarz klubu lub Terminarz drużyny › Eksport). Najpierw zobaczysz podgląd – dane zostaną przejęte dopiero po twoim potwierdzeniu. Ponowny import aktualizuje istniejące mecze zamiast tworzyć je podwójnie.",
