  "Lege das Mitglied an und ordne es danach einer Mannschaft zu. Den App-Zugang erhält es später über eine Einladung.": "Utwórz członka i potem przypisz go do drużyny. Dostęp do aplikacji dostanie później przez zaproszenie.",
