  "Mindestens 10 Zeichen. Eine Wortfolge oder ein Satz ist sicherer und leichter zu merken als ein kurzes Passwort mit Sonderzeichen.": "Co najmniej 10 znaków. Ciąg słów lub zdanie jest bezpieczniejsze i łatwiejsze do zapamiętania niż krótkie hasło ze znakami specjalnymi.",
  "Mindestens eine importierte Person hat schon ein Konto. Der Import lässt sich nicht mehr rückgängig machen.": "Co najmniej jedna zaimportowana osoba ma już konto. Importu nie można już cofnąć.",
  "Mindestens zwei Buchstaben eingeben.": "Wpisz co najmniej dwie litery.",
  "Mini-Forum": "Mini forum",
  "Mit Ablaufdatum": "Z datą wygaśnięcia",
  "Mit App-Zugang": "Z dostępem do aplikacji",
  "Mit dem Start wird {0} zur laufenden Saison. Mannschaftskassen, Mannschaftsdokumente und künftige Termine gehen auf die neuen Mannschaften über. Zuordnungen und Aufgaben der alten Saison enden. Das lässt sich nicht rückgängig machen.": "Po rozpoczęciu {0} staje się bieżącym sezonem. Kasy drużyn, dokumenty drużyn i przyszłe terminy przechodzą na nowe drużyny. Przypisania i zadania starego sezonu się kończą. Tego nie można cofnąć.",
  "Mit den Pfeilen verschiebst du das Datum um einen Tag. Tippst du auf das Datum selbst, öffnet sich ein Kalender: Wische oder tippe auf die Pfeile, um den Monat zu wechseln, tippe auf einen Tag zum Auswählen oder wähle „Heute“. Nicht erlaubte Tage sind ausgegraut.": "Strzałkami przesuwasz datę o jeden dzień. Gdy dotkniesz samej daty, otwiera się kalendarz: przesuwaj lub dotykaj strzałek, aby zmienić miesiąc, dotknij dnia, aby go wybrać, lub wybierz „Dziś“. Niedozwolone dni są wyszarzone.",
  "Mit den Schreibweisen aus dem DFBnet ordnet der Spielplan-Import die Spiele richtig zu.": "Dzięki pisowni z DFBnet import terminarza prawidłowo przypisuje mecze.",
  "Mit der Anschrift füllt Clubroof Spendenbescheinigungen aus; die Zeitzone bestimmt Fristen und Terminzeiten.": "Na podstawie adresu Clubroof wypełnia potwierdzenia darowizn; strefa czasowa określa terminy i godziny terminów.",
  "Mit der Zwei-Faktor-Anmeldung braucht jede neue Anmeldung zusätzlich einen Code. Für das Administrationskonto empfehlen wir sie.": "Przy logowaniu dwuskładnikowym każde nowe logowanie wymaga dodatkowo kodu. Dla konta administracji zalecamy je.",
  "Mit dieser E-Mail-Adresse gibt es bereits ein Konto. Bitte melde dich an oder nutze „Passwort vergessen“.": "Z tym adresem e-mail istnieje już konto. Zaloguj się lub użyj „Zapomniałem(-am) hasła“.",
  "Mit Einladungslink oder Einladungscode (auch per QR-Code scannen) trittst du deinem Verein bei – der Verein wird danach auf diesem Gerät gemerkt. Hast du schon ein Konto, melde dich mit E-Mail und Passwort an („Zeigen“ macht das Passwort sichtbar). Einen neuen Verein richtest du mit dem Einrichtungscode (Format CR-XXXX-XXXX) ein, den du von Clubroof nach Zahlungseingang erhältst; er gilt einmal.": "Przez link zaproszenia lub kod zaproszenia (także przez zeskanowanie kodu QR) dołączasz do swojego klubu – klub jest potem zapamiętywany na tym urządzeniu. Jeśli masz już konto, zaloguj się adresem e-mail i hasłem („Pokaż“ odsłania hasło). Nowy klub konfigurujesz kodem konfiguracji (format CR-XXXX-XXXX), który dostaniesz od Clubroof po wpłynięciu płatności; jest jednorazowy.",
  "Mit Face ID oder Fingerabdruck entsperren": "Odblokuj przez Face ID lub odcisk palca",
  "Mit festen Trainingszeiten stehen die Termine sofort im Kalender, und Zu- und Absagen funktionieren ab dem ersten Tag.": "Przy stałych godzinach treningów terminy od razu są w kalendarzu, a potwierdzenia i odwołania działają od pierwszego dnia.",
  "Mit Namen": "Z nazwiskami",
