  "Mitglieder melden Zahlungen in ihrem Konto. Du siehst sie in der Kassenverwaltung unter „Zahlungsmeldungen“ und bestätigst mit „Eingegangen“ – dann wird die Einzahlung gebucht – oder „Nicht gefunden“.": "Członkowie zgłaszają płatności na swoim koncie. Widzisz je w zarządzaniu kasą w „Zgłoszenia płatności“ i potwierdzasz przez „Wpłynęło“ – wtedy wpłata jest księgowana – lub „Nie znaleziono“.",
  "Mitglieder ohne Geburtsdatum werden bei der Jugend-Regel übersprungen und bleiben ohne Beitragsart; Mitglieder mit laufender Beitragsart werden nie verändert.": "Członkowie bez daty urodzenia są pomijani przy regule młodzieżowej i pozostają bez rodzaju składki; członkowie z trwającym rodzajem składki nigdy nie są zmieniani.",
  "Mitglieder reichen Auslagen und Fahrtkosten ein, die Kassenführung prüft sie. Lege fest, wie streng das geschieht.": "Członkowie zgłaszają wydatki i koszty przejazdu, kasa je sprawdza. Ustal, jak rygorystycznie.",
