  "Nach Beginn eines Termins hakst du ab, wer wirklich da war (vorausgewählt sind die Zusagen). Danach zählt für Trainingsquote und Statistik die Anwesenheit statt der Zusage. Auf Start erinnert dich ein Hinweis an Trainings der letzten Woche.": "Po rozpoczęciu terminu odhaczasz, kto naprawdę był (wstępnie zaznaczone są potwierdzenia). Potem do wskaźnika obecności na treningach i statystyki liczy się obecność zamiast potwierdzenia. Na stronie głównej wskazówka przypomina o treningach z ostatniego tygodnia.",
  "nach Beschluss der Versammlung": "wg uchwały zebrania",
  "Nach dem Anlegen bekommst du einen fertigen Einladungstext zum Weiterschicken.": "Po utworzeniu dostaniesz gotowy tekst zaproszenia do przesłania dalej.",
