  "Name oder Nummer": "Nazwa lub numer",
  "Name und Adresse der Sportanlage. Sie erscheinen bei Terminen, mit Link zur Karten-App.": "Nazwa i adres obiektu sportowego. Pojawiają się przy terminach, z linkiem do aplikacji map.",
  "Name, Beschreibung …": "Nazwa, opis …",
  "Name, E-Mail und Telefon sind im ganzen Verein sichtbar": "Imię i nazwisko, e-mail i telefon są widoczne w całym klubie",
  "Name, Kontaktdaten, Mannschaftszugehörigkeit, Zu- und Absagen sowie – nur für Berechtigte – Kassendaten. Gründe für Abwesenheiten sind nur für Trainer und Verantwortliche sichtbar.": "Imię i nazwisko, dane kontaktowe, przynależność do drużyny, potwierdzenia i odwołania oraz – tylko dla uprawnionych – dane kasowe. Powody nieobecności są widoczne tylko dla trenerów i osób odpowiedzialnych.",
  "Namen der Plätze und Kabinen eurer Sportanlage": "Nazwy boisk i szatni waszego obiektu sportowego",
