  "Nein": "Nie",
  "Nein, es gehört der Mannschaft": "Nie, należy do drużyny",
  "Nein. In der Ruhezeit (22 bis 7 Uhr) gibt es keine Push-Nachrichten außer bei dringenden Meldungen. Alles andere wartet bis zum Morgen.": "Nie. W czasie ciszy (22 do 7) nie ma powiadomień push poza pilnymi komunikatami. Wszystko inne czeka do rana.",
  "Nein. Trage eine Abwesenheit ein (Urlaub, Verletzt, Krank, Sonstiges). Alle betroffenen Termine werden automatisch abgesagt, das Trainerteam sieht es sofort. Löschst du die Abwesenheit, werden die automatischen Absagen zurückgenommen.": "Nie. Wpisz nieobecność (urlop, kontuzja, choroba, inne). Wszystkie dotknięte terminy zostaną automatycznie odwołane, sztab szkoleniowy widzi to od razu. Jeśli usuniesz nieobecność, automatyczne odwołania zostaną cofnięte.",
  "neu": "nowe",
