  "Nur Admins: Verwaltung › Rollen und Rechte › „Neue Rolle“. Du gibst Name, Beschreibung und den Geltungsbereich (Verein, Abteilung, Mannschaft) an und wählst die Rechte in Klartext; mit „Start als Kopie von“ übernimmst du eine vorhandene Rolle. Sensible Rechte tragen ein Schloss. Vereinsweite Rechte (Verein, Vereinskasse, Mitglieder) gibt es nur in vereinsweiten Rollen, und du kannst nur Rechte vergeben, die du selbst hast. Standardrollen sind geschützt – dort gibt es „Kopie anpassen“. Gelöschte Rollen lassen sich wiederherstellen; Personen stellst du beim Löschen auf eine andere Rolle um. In der Übersicht zeigen die Reiter Rollen, Personen und Matrix den Stand; bei einer Person zeigt „Was darf diese Person?“ jedes Recht mit seiner Quelle.": "Tylko administratorzy: Administracja › Role i uprawnienia › „Nowa rola“. Podajesz nazwę, opis i zakres obowiązywania (klub, sekcja, drużyna) i wybierasz uprawnienia otwartym tekstem; przez „Zacznij od kopii“ przejmujesz istniejącą rolę. Uprawnienia wrażliwe mają kłódkę. Uprawnienia całego klubu (klub, kasa klubu, członkowie) są tylko w rolach obejmujących cały klub i możesz nadawać tylko uprawnienia, które sam(a) masz. Role standardowe są chronione – tam jest „Dostosuj kopię“. Usunięte role można przywrócić; osoby przy usuwaniu przestawiasz na inną rolę. W przeglądzie zakładki Role, Osoby i Macierz pokazują stan; przy osobie „Co może ta osoba?“ pokazuje każde uprawnienie z jego źródłem.",
