  "Rot steht für Dringendes, Orange für etwas, das du erledigen sollst, Blau für Informationen und Grün für Erledigtes. Farben haben immer auch eine Beschriftung. Kleine Zahlen an Kacheln zeigen offene Punkte, z. B. unbeantwortete Umfragen.": "Czerwony oznacza pilne, pomarańczowy coś, co masz zrobić, niebieski informacje, a zielony rzeczy załatwione. Kolory zawsze mają też opis. Małe liczby na kafelkach pokazują otwarte punkty, np. ankiety bez odpowiedzi.",
