  "Schalte ein, was deine Mannschaft nutzt. Ausgeschaltete Funktionen verschwinden für alle in der Mannschaft. Was der Verein oder die Abteilung ausgeschaltet hat, bleibt aus.": "Włącz to, czego używa twoja drużyna. Wyłączone funkcje znikają dla wszystkich w drużynie. To, co wyłączył klub lub sekcja, pozostaje wyłączone.",
