  "So funktioniert die App. Tippe auf eine Frage, um die Antwort zu lesen – oder suche nach einem Stichwort. Fragen zum Verein selbst beantworten dir die Ansprechpartner.": "Tak działa aplikacja. Dotknij pytania, aby przeczytać odpowiedź – lub wyszukaj hasło. Na pytania dotyczące samego klubu odpowiedzą ci osoby kontaktowe.",
