  "So lang wie die Saison des Vereins, z. B. Juli bis Juni": "Tak długo jak sezon klubu, np. lipiec–czerwiec",
  "So sieht ein normaler Text in dieser Größe aus.": "Tak wygląda zwykły tekst w tym rozmiarze.",
