  "So wenig wie nötig: Gründe für Absagen und Abwesenheiten sehen nur das Trainerteam und du. Kontaktdaten sehen nur die Personen, die du freigibst. Eltern sehen die Daten ihrer Kinder. Trainingsbeteiligung und Kassenstand sieht die eigene Mannschaft.": "Tyle, ile trzeba: powody odwołań i nieobecności widzą tylko sztab szkoleniowy i ty. Dane kontaktowe widzą tylko osoby, którym je udostępnisz. Rodzice widzą dane swoich dzieci. Udział w treningach i stan kasy widzi własna drużyna.",
