  "Sportliche Leitung": "Dyrekcja sportowa",
  "Sportliche Leitung, Jugendleitung und Vorstand sehen im Reiter „Team“ eine Übersicht über die Abteilungen (Senioren, Frauen, Jugend) – ohne Zugriff in die einzelnen Mannschaften. Oben stehen die Kennzahlen, darunter eine Karte je Mannschaft mit Kader, Trainerteam, Trainingsbeteiligung der letzten 4 Wochen und dem nächsten Spiel. Die Ampel gilt nur für die Trainingsbeteiligung: gut ab 65 %, mittel 50–64 %, niedrig darunter; bei weniger als 3 erfassten Einheiten steht „zu wenig Daten“. Wer auch selbst in einer Mannschaft ist, schaltet oben zwischen „Meine Mannschaft“ und „Übersicht“ um.": "Dyrekcja sportowa, kierownictwo młodzieży i zarząd widzą w zakładce „Zespół“ przegląd sekcji (seniorzy, kobiety, młodzież) – bez dostępu do poszczególnych drużyn. U góry są wskaźniki, pod nimi karta każdej drużyny z kadrą, sztabem szkoleniowym, udziałem w treningach z ostatnich 4 tygodni i najbliższym meczem. Sygnalizacja dotyczy tylko udziału w treningach: dobry od 65 %, średni 50–64 %, niski poniżej; przy mniej niż 3 zarejestrowanych jednostkach pojawia się „za mało danych“. Kto sam jest też w drużynie, przełącza się u góry między „Moja drużyna“ a „Przegląd“.",
