  "Strafen und ihre Beträge legen Trainerteam und Kassenwart im Strafenkatalog fest („Team → Strafenkatalog“). Wurde dir eine Strafe vergeben, steht sie als offener Betrag auf deinem Konto und du bekommst eine Benachrichtigung.": "Kary i ich kwoty ustalają sztab szkoleniowy i skarbnik w taryfikatorze kar („Zespół → Taryfikator kar“). Jeśli nałożono na ciebie karę, widnieje jako kwota do zapłaty na twoim koncie i dostajesz powiadomienie.",
