  "Termine, News und Abwesenheiten sind immer dabei. Wähle, was eure Mannschaften zusätzlich brauchen.": "Terminy, aktualności i nieobecności są zawsze. Wybierz, czego wasze drużyny potrzebują dodatkowo.",
  "Testspiel": "Sparing",
  "Text der Buchung": "Tekst księgowania",
  "Text der Detailseite": "Tekst strony szczegółów",
