  "Text kopieren": "Skopiuj tekst",
  "Text wie „Jahr 2026“; leer = Fälligkeitsdatum": "Tekst, np. „Rok 2026“; puste = data płatności",
  "Thema": "Temat",
  "Thema bearbeiten": "Edytuj temat",
  "Thema eröffnen": "Otwórz temat",
  "Themen": "Tematy",
  "Themen eröffnen Verantwortliche im Verein.": "Tematy otwierają osoby odpowiedzialne w klubie.",
  "Themen schließt das Moderationsteam.": "Tematy zamyka zespół moderatorów.",
  "Tipp: Ort in der Karten-App suchen, „Teilen“ wählen und den Link hier einfügen. Ohne Link nutzt „Route“ die eingetragene Adresse.": "Wskazówka: znajdź miejsce w aplikacji map, wybierz „Udostępnij“ i wklej tu link. Bez linku „Trasa“ używa wpisanego adresu.",
  "Tippe auf der Anmeldeseite auf „Passwort vergessen?“. Du bekommst einen Link per E-Mail, mit dem du ein neues Passwort festlegst. Im Konto kannst du es jederzeit ändern.": "Na stronie logowania dotknij „Zapomniałeś(-aś) hasła?“. Dostaniesz e-mailem link, przez który ustawisz nowe hasło. W koncie możesz je w każdej chwili zmienić.",
  "Tippe auf die Uhrzeit: Es öffnet sich ein Fenster mit zwei Drehwalzen wie bei einem Wecker – links die Stunde, rechts die Minute (in 5er-Schritten). Wische oder scrolle, bis die richtige Zeit in der Mitte steht, und tippe auf „Übernehmen“. Beim Anlegen eines Termins wählst du Beginn und Ende; die Dauer zeigt die App darunter.": "Dotknij godziny: otworzy się okno z dwoma bębnami jak w budziku – po lewej godzina, po prawej minuta (co 5). Przesuwaj lub przewijaj, aż właściwa godzina będzie pośrodku, i dotknij „Przejmij“. Przy tworzeniu terminu wybierasz początek i koniec; czas trwania aplikacja pokazuje pod spodem.",
  "Tippe auf einen Spieler, um seine Rückmeldung zu korrigieren.": "Dotknij zawodnika, aby poprawić jego odpowiedź.",
  "Tippe im Termin bei „Teilnehmer“ auf eine Person und wähle Zusage, Unsicher oder Absage. Das geht auch nach Ablauf der Frist (bis eine Woche nach Beginn).": "W terminie przy „Uczestnicy“ dotknij osoby i wybierz potwierdzenie, niepewne lub odwołanie. Można to zrobić także po upływie terminu (do tygodnia po rozpoczęciu).",
  "Tippe in „Mein Konto“ auf „Bezahlen / Zahlung melden“. Du siehst die Bezahlinfos der Mannschaft (IBAN zum Kopieren, PayPal, bar). Nach dem Bezahlen tippst du „Ich habe bezahlt“. Sobald die Kasse den Eingang bestätigt hat, ist dein Konto ausgeglichen.": "W „Moje konto“ dotknij „Zapłać / zgłoś płatność“. Zobaczysz informacje o płatnościach drużyny (IBAN do skopiowania, PayPal, gotówka). Po zapłaceniu dotykasz „Zapłaciłem(-am)“. Gdy kasa potwierdzi wpływ, twoje konto jest wyrównane.",
  "Tippe oben rechts auf die Lupe und gib mindestens zwei Buchstaben ein. Du findest Termine, Mitglieder, News und Mannschaften. Personen siehst du nur, wenn du auch sonst ihr Profil sehen darfst (z. B. aus deiner Mannschaft oder deine Kinder).": "Dotknij lupy w prawym górnym rogu i wpisz co najmniej dwie litery. Znajdziesz terminy, członków, aktualności i drużyny. Osoby widzisz tylko, jeśli i tak możesz zobaczyć ich profil (np. z twojej drużyny lub twoje dzieci).",
  "Titel": "Tytuł",
  "Tor": "Bramka",
  "Tor {0}": "Bramka {0}",
  "Tore": "Bramki",
