  "Torschütze und Vorlage müssen verschieden sein.": "Strzelec bramki i asystent muszą być różni.",
  "Torschützen": "Strzelcy bramek",
  "Torwart": "Bramkarz",
  "Trage ein, wann du nicht verfügbar bist. Betroffene Termine werden automatisch abgesagt, dein Trainerteam sieht es sofort.": "Wpisz, kiedy jesteś niedostępny(-a). Dotknięte terminy zostaną automatycznie odwołane, twój sztab szkoleniowy widzi to od razu.",
  "Trage ein, wann du oder deine Kinder nicht verfügbar bist. Betroffene Termine werden automatisch abgesagt, dein Trainerteam sieht es sofort.": "Wpisz, kiedy ty lub twoje dzieci jesteście niedostępni. Dotknięte terminy zostaną automatycznie odwołane, twój sztab szkoleniowy widzi to od razu.",
  "Trainer": "Trener",
  "Trainer {0}": "Trener {0}",
  "Trainer entscheiden für ihre Mannschaft, die Verwaltung kann immer freigeben": "Trenerzy decydują dla swojej drużyny; administracja może zawsze zatwierdzić",
  "Trainer sehen Kader und Rückmeldungen und können Termine anlegen. Co-Trainer haben dieselben Rechte.": "Trenerzy widzą kadrę i odpowiedzi i mogą tworzyć terminy. Asystenci trenera mają te same uprawnienia.",
