  "Über das Schild-Symbol oben rechts oder „Ich → Admin-Verwaltung“ oder „Verein → Meine Vereinsaufgaben → Verwaltung“. Mit „Zur App“ kehrst du zur normalen App zurück. Unten wechselst du zwischen Übersicht, Mitgliedern, Teams, Festen und News.": "Przez ikonę tarczy w prawym górnym rogu lub „Ja → Administracja“ albo „Klub → Moje zadania klubowe → Administracja“. Przez „Do aplikacji“ wracasz do zwykłej aplikacji. Na dole przełączasz się między Przeglądem, Członkami, Zespołami, Imprezami i Aktualnościami.",
