  "Übliche Strafen als Vorlage – abwählen, was ihr nicht wollt. Beträge und weitere Strafen änderst du später.": "Typowe kary jako szablon – odznacz to, czego nie chcecie. Kwoty i kolejne kary zmienisz później.",
