  "Umlage: Gesamtbetrag auf gewählte Personen aufteilen oder festen Betrag je Person fordern. Beiträge: z. B. 5 € monatlich, die App bucht sie allen Spielern zum Fälligkeitstag. Getränke: Preis festlegen und je Person Striche zählen. Alle Betroffenen werden benachrichtigt.": "Zrzutka: podziel łączną kwotę na wybrane osoby lub pobierz stałą kwotę od osoby. Składki: np. 5 € miesięcznie, aplikacja księguje je wszystkim zawodnikom w dniu płatności. Napoje: ustal cenę i zliczaj kreski na osobę. Wszyscy zainteresowani są powiadamiani.",
