  "Vertretung ist wichtig: Empfohlen sind mindestens zwei Personen mit Administrationsrechten. Weitere Rollen vergibst du später unter Verwaltung › Rollen & Aufgaben.": "Zastępstwo jest ważne: zalecane są co najmniej dwie osoby z uprawnieniami administracyjnymi. Kolejne role nadasz później w Administracja › Role i zadania.",
