  "Verwaltungsrechte schützen Daten aller Mitglieder. Ein zweiter Faktor (Authenticator-App oder Code per E-Mail) verhindert, dass ein gestohlenes Passwort allein genügt.": "Uprawnienia administracyjne chronią dane wszystkich członków. Drugi składnik (aplikacja uwierzytelniająca lub kod e-mailem) sprawia, że samo skradzione hasło nie wystarcza.",
