  "Zuschüsse: Unter „Vereinskasse → Buchung → Zuschüsse“ legst du Förderungen mit Geber, Betrag und Frist für den Verwendungsnachweis an und führst sie von „Geplant“ über „Beantragt“ und „Bewilligt“ bis zum Eingang (Buchung als Einnahme); überfällige Nachweise sind rot. Sponsoren: Beim Buchen einer Einnahme wählst du den Sponsor; unter „Sponsoren“ siehst du die Einnahmen je Sponsor und Jahr. Mannschaftszuschuss: Ausgabe der Vereinskasse und Einnahme der Mannschaftskasse in einem Schritt. Inventar: Unter „Planung → Inventar“ erfasst du Anschaffungen mit Wert und Standort; Gegenstände werden mit Grund ausgesondert, nicht gelöscht.": "Dopłaty: w „Kasa klubu → Księgowanie → Dopłaty“ tworzysz dofinansowania z darczyńcą, kwotą i terminem rozliczenia wykorzystania i prowadzisz je od „Zaplanowano“ przez „Złożono wniosek“ i „Przyznano“ aż do wpływu (księgowanie jako przychód); zaległe rozliczenia są czerwone. Sponsorzy: przy księgowaniu przychodu wybierasz sponsora; w „Sponsorzy“ widzisz przychody wg sponsora i roku. Dopłata dla drużyny: wydatek kasy klubu i przychód kasy drużyny w jednym kroku. Inwentarz: w „Planowanie → Inwentarz“ zapisujesz zakupy z wartością i lokalizacją; przedmioty są wycofywane z uzasadnieniem, nie usuwane.",
